// Deliberately simplified flight model, in game metres and seconds.
export const G=9,THRUST=24,TARGET=670,GOAL=250;
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
export function createFlight(mode='launch'){return {mode,status:'ready',phase:mode==='launch'?'ascent':'descent',x:mode==='launch'?220:270,y:mode==='launch'?0:240,vx:mode==='launch'?0:14,vy:mode==='launch'?0:-8,fuel:100,time:0,peak:0,throttle:0,steer:0,airborne:mode==='land',reached:mode==='land',reason:''};}
export function assistedControls(s){const liningUp=(Math.abs(TARGET-s.x)>28||Math.abs(s.vx)>4)&&s.y<65;const vy=s.phase==='descent'&&liningUp?clamp((50-s.y)*.7,-5,5):s.phase==='ascent'?Math.min(30,Math.max(14,(GOAL-s.y)*.6)):-Math.min(23,Math.max(2,s.y*.35));return {throttle:clamp((G+(vy-s.vy)*1.8)/THRUST,0,1),steer:clamp(((TARGET-s.x)*.12-s.vx*.9)/12,-1,1)};}
export function stepFlight(s,input,dt){if(s.status!=='flying')return s;dt=clamp(dt,0,.025);s.time+=dt;const throttle=clamp(input.throttle||0,0,1),steer=clamp(input.steer||0,-1,1),cost=(throttle*3.5+Math.abs(steer)*.6)*dt,available=cost?Math.min(1,s.fuel/cost):1;s.throttle=throttle*available;s.steer=steer*available;s.fuel=Math.max(0,s.fuel-cost);s.vx+=(s.steer*12-s.vx*.05)*dt;s.vy+=(s.throttle*THRUST-G)*dt;s.x+=s.vx*dt;s.y+=s.vy*dt;s.peak=Math.max(s.peak,s.y);if(s.y>2)s.airborne=true;if(s.mode==='launch'&&!s.reached&&s.y>=GOAL){s.reached=true;s.phase='descent';}
if(s.x<25||s.x>875||s.y>370){s.status='crashed';s.reason='Outside the flight corridor. Use shorter steering burns.';}
if(s.y<=0){s.y=0;if(!s.airborne){s.vy=0;s.vx=0;s.x=220;}else{const onPad=Math.abs(s.x-TARGET)<=42,soft=s.vy>=-6&&Math.abs(s.vx)<=5;if(onPad&&soft&&s.reached){s.status='landed';s.reason='Soft touchdown. Rocket recovered!';}else{s.status='crashed';s.reason=!onPad?'Touchdown missed the landing pad.':!soft?'Touchdown was too fast. Brake earlier.':'Reach the 250 m checkpoint before landing.';}}}return s;}
